def loud(text: str) -> str:
    return text.upper()

def apply(text: str, strategy) -> str:
    return strategy(text)

print(apply("go", loud))

def make_prefix(prefix: str):
    def add_prefix(text: str) -> str:
        return prefix + text
    return add_prefix

star = make_prefix("* ")
print(star("note"))

def announce(func):
    def wrapper():
        print("start")
        func()
    return wrapper

@announce
def work():
    print("work")

work()

from pydantic import BaseModel, model_validator

class Range(BaseModel):
    start: int
    end: int

    @model_validator(mode="after")
    def check_order(self):
        if self.end < self.start:
            raise ValueError("end must be after start")
        return self
